// A JOIN ARM'S KEY IS THE COLUMN THE QUERY WROTE — #1299 and #1302, on FIVE
// ARMS (arc JP; ADR-0026 §3d, ADR-0021 §1s).
//
// #1299, the seam enumerated once:
//
//	{the same item table x2, x3, x4; three different tables sharing every
//	 column name; mixed x3, x4}
//	x {a per-arm ON filter on every arm, on some, on none}
//	x {filters as IN lists, equalities, ranges}
//	x {INNER, LEFT, RIGHT, INNER and LEFT alternating}
//	x {the key under a name every relation has (sameName), under a name every
//	   relation has holding a DIFFERENT value in each (crossName — the
//	   issue's `s.order_id = o.id`), under a name only the outer has (ownName)}
//	x {star (every arm keyed on the outer relation), chain (each on the last)}
//
// over jp_o / jp_i / jp_j / jp_k (arc_jp_fixture_test.go). At base 83cd4a93
// the join reorderer resolved an ON conjunct's relations by bare column name,
// so where one table is joined three or more times it hung `c.oid = o.k` on a
// join of two item copies and the key bound a sibling's column — a wrong
// PAIRING with no error.
//
// #1302: a correlated equality whose OUTER side is an expression —
//
//	{o.k, o.k - 0, o.k + 1, CAST, a function, coalesce, two outer columns}
//	x {inner side left, outer side left, inner side an expression}
//	x {JOIN / LEFT / comma LATERAL, ORDER BY LIMIT 1 and 2, COUNT(*), SUM,
//	   a bare star, EXISTS, EXISTS LIMIT 1, NOT EXISTS, IN, scalar}
//
// over lt_o / lt_i. At base the lowering dropped the key slot at the join
// while the equality — no hash key, since its outer side is no column — was
// evaluated ABOVE the join, reading NULL: zero rows.

type jpCell struct{ name, sql string }

type jpArm struct {
	name string
	run  func(string) string
}

// jpArms: the single-process engine, the same at a 512 KiB budget, the
// three-worker stage DAG, the DAG with every build shuffled, and the
// coordinator's small-query fast path at its production threshold.
func jpArms(t *testing.T, ctx context.Context) []jpArm {
	t.Helper()
	single := tmdStandalone(t, ctx)
	spilled := na2Standalone(t, ctx, 512*1024)
	infra := tmdInfra(t, ctx)
	tmdWriteTables(t, ctx, infra, nil)
	coord := tmdCoordinator(t, ctx, infra)
	infraB := tmdInfra(t, ctx)
	tmdWriteTables(t, ctx, infraB, nil)
	coordB := tmdCoordinator(t, ctx, infraB, func(c *Config) { c.BroadcastBytesOverride = 1 })
	infraF := tmdInfra(t, ctx)
	tmdWriteTables(t, ctx, infraF, nil)
	fast := tmdCoordinator(t, ctx, infraF, func(c *Config) { c.LocalFastPathBytes = DefaultLocalFastPathBytes })
	return []jpArm{
		{"single", func(s string) string { return r1Single(ctx, single, s) }},
		{"spilled512k", func(s string) string { return r1Single(ctx, spilled, s) }},
		{"dag", func(s string) string { return r1DAG(ctx, coord, s) }},
		{"dag-shuffled", func(s string) string { return r1DAG(ctx, coordB, s) }},
		{"fastpath", func(s string) string { return r1DAG(ctx, fast, s) }},
	}
}

func jpRun(t *testing.T, arms []jpArm, cells []jpCell, want map[string]string, refuses map[string]string, pins map[string]map[string]string) {
	t.Helper()
	seen := map[string]bool{}
	for _, tc := range cells {
		w, ok := want[tc.name]
		if !ok {
			t.Fatalf("%s: no PostgreSQL row set recorded", tc.name)
		}
		seen[tc.name] = true
		t.Run(tc.name, func(t *testing.T) {
			for _, arm := range arms {
				got := arm.run(tc.sql)
				if pin, pinned := pins[tc.name][arm.name]; pinned {
					// A PIN THAT STARTS AGREEING FAILS: delete it.
					if got == w {
						t.Errorf("%s\n  arm  %s\n  the pinned divergence is GONE and the arm answers "+
							"PostgreSQL's %s: delete this arm's pin", tc.sql, arm.name, w)
					} else if got != pin {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  pinned %s (PostgreSQL answers %s)",
							tc.sql, arm.name, got, pin, w)
					}
					continue
				}
				if class, refused := refuses[tc.name]; refused {
					// A REFUSAL THAT STARTS ANSWERING FAILS: assert
					// PostgreSQL's row set and delete the refusal.
					if !strings.HasPrefix(got, "ERR ") || !strings.Contains(got, class) {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  every arm must refuse with %q "+
							"(PostgreSQL answers %s)", tc.sql, arm.name, got, class, w)
					}
					continue
				}
				if got != w {
					t.Errorf("%s\n  arm  %s\n  got  %s\n  want %s (PostgreSQL 17.11)",
						tc.sql, arm.name, got, w)
				}
			}
		})
	}
	for name := range want {
		if !seen[name] {
			t.Errorf("%s: a PostgreSQL row set is recorded for a cell the table no longer writes", name)
		}
	}
}

func TestArcJPASelfJoinArmPairsTheRowsItsQualifierNamesOnEveryArm(t *testing.T) {
	if testing.Short() {
		t.Skip("-short: five arms over the 1008-cell #1299 seam table")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
	t.Cleanup(cancel)
	jpRun(t, jpArms(t, ctx), jpPairCells(), jpPairPostgres, jpPairRefuses, jpArmPins)
}

func TestArcJPALateralOuterExpressionKeyAnswersOnEveryArm(t *testing.T) {
	if testing.Short() {
		t.Skip("-short: five arms over the 231-cell #1302 seam table")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
	t.Cleanup(cancel)
	jpRun(t, jpArms(t, ctx), jpKeyCells(), jpKeyPostgres, jpKeyRefuses, jpArmPins)
}
